"""Text Analysis Engine for ProseAI."""
import re
import math
from typing import Dict, Any


class TextAnalyzer:
    """Analyzes text for readability metrics and statistics."""

    def _count_syllables(self, word: str) -> int:
        """Estimate syllable count using vowel-group heuristic."""
        word = word.lower().strip()
        if not word:
            return 0
        vowels = "aeiouy"
        count = 0
        prev_vowel = False
        for char in word:
            is_vowel = char in vowels
            if is_vowel and not prev_vowel:
                count += 1
            prev_vowel = is_vowel
        # Handle silent e
        if word.endswith("e") and count > 1:
            count -= 1
        # Every word has at least one syllable
        return max(1, count)

    def _split_sentences(self, text: str) -> list:
        """Split text into sentences."""
        sentences = re.split(r'(?<=[.!?])\s+', text.strip())
        return [s for s in sentences if s.strip()]

    def _flesch_reading_ease(self, words: list, sentences: list, syllables: int) -> float:
        """Calculate Flesch Reading Ease score (0-100, higher = easier)."""
        if not sentences or not words:
            return 0.0
        asl = len(words) / len(sentences)
        asw = syllables / len(words)
        score = 206.835 - (1.015 * asl) - (84.6 * asw)
        return round(max(0, min(100, score)), 2)

    def _gunning_fog(self, words: list, sentences: list) -> float:
        """Calculate Gunning Fog Index (years of education needed)."""
        if not sentences or not words:
            return 0.0
        complex_words = [w for w in words if self._count_syllables(w) >= 3]
        asl = len(words) / len(sentences)
        pct_complex = (len(complex_words) / len(words)) * 100
        return round(0.4 * (asl + pct_complex), 2)

    def _reading_level_label(self, flesch: float) -> str:
        """Convert Flesch score to a human-readable level."""
        if flesch >= 90:
            return "Very Easy (5th grade)"
        elif flesch >= 80:
            return "Easy (6th grade)"
        elif flesch >= 70:
            return "Fairly Easy (7th grade)"
        elif flesch >= 60:
            return "Standard (8th-9th grade)"
        elif flesch >= 50:
            return "Fairly Difficult (10th-12th grade)"
        elif flesch >= 30:
            return "Difficult (College level)"
        else:
            return "Very Difficult (Graduate level)"

    def analyze(self, text: str) -> Dict[str, Any]:
        """Analyze text and return comprehensive metrics."""
        words = re.findall(r'\b[a-zA-Z]+\b', text)
        sentences = self._split_sentences(text)
        total_syllables = sum(self._count_syllables(w) for w in words)

        flesch = self._flesch_reading_ease(words, sentences, total_syllables)
        fog = self._gunning_fog(words, sentences)

        return {
            "word_count": len(words),
            "sentence_count": len(sentences),
            "avg_sentence_length": round(len(words) / max(1, len(sentences)), 2),
            "flesch_reading_ease": flesch,
            "gunning_fog": fog,
            "reading_level_label": self._reading_level_label(flesch),
        }

"""Text Transformation Engine for ProseAI."""
import httpx
import asyncio
from typing import Optional, Dict, Any
from app.config import Settings
from app.prompts import PromptTemplateEngine


class TextTransformer:
    """Rewrites text in various modes using LLM or rule-based fallback."""

    MODES = ["concise", "simplify", "formalize", "casualize", "summarize", "expand"]

    def __init__(self, settings: Settings):
        self.settings = settings
        self.prompt_engine = PromptTemplateEngine()
        self.api_key = settings.OPENAI_API_KEY
        self.api_base = getattr(settings, "LLM_BASE_URL", "https://api.openai.com/v1")
        self.model = getattr(settings, "LLM_MODEL", "gpt-4o-mini")

    async def _call_llm(self, system_prompt: str, user_prompt: str) -> str:
        """Call an OpenAI-compatible LLM endpoint."""
        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json",
        }
        payload = {
            "model": self.model,
            "messages": [
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": user_prompt},
            ],
            "temperature": 0.7,
            "max_tokens": 2048,
        }
        async with httpx.AsyncClient() as client:
            response = await client.post(
                f"{self.api_base}/chat/completions",
                json=payload,
                headers=headers,
                timeout=30.0,
            )
            response.raise_for_status()
            data = response.json()
            return data["choices"][0]["message"]["content"]

    def _rule_based_concise(self, text: str) -> str:
        """Simple rule-based conciseness: remove filler words."""
        fillers = [
            "very", "really", "just", "quite", "rather", "somewhat",
            "basically", "actually", "literally", "definitely", "certainly",
        ]
        words = text.split()
        filtered = [w for w in words if w.lower().strip(".,!?;:") not in fillers]
        return " ".join(filtered)

    def _rule_based_simplify(self, text: str) -> str:
        """Replace complex words with simpler alternatives."""
        replacements = {
            "utilize": "use", "implement": "set up", "facilitate": "help",
            "approximately": "about", "subsequently": "then",
            "demonstrate": "show", "sufficient": "enough",
            "commence": "start", "terminate": "end",
            "endeavor": "try", "numerous": "many",
        }
        result = text
        for complex_word, simple_word in replacements.items():
            result = result.replace(complex_word, simple_word)
            result = result.replace(complex_word.capitalize(), simple_word.capitalize())
        return result

    def _rule_based_fallback(self, text: str, mode: str) -> str:
        """Fallback transformations when no API key is available."""
        if mode == "concise":
            return self._rule_based_concise(text)
        elif mode == "simplify":
            return self._rule_based_simplify(text)
        elif mode == "formalize":
            return text.replace("don't", "do not").replace("can't", "cannot")
        elif mode == "casualize":
            return text.replace("do not", "don't").replace("cannot", "can't")
        elif mode == "summarize":
            sentences = text.split(". ")
            return ". ".join(sentences[:max(1, len(sentences) // 3)]) + "."
        elif mode == "expand":
            return text  # No good rule-based expansion
        return text

    async def rewrite(self, text: str, mode: str, config: Optional[Dict[str, Any]] = None) -> str:
        """Rewrite text in the specified mode."""
        if mode not in self.MODES:
            raise ValueError(f"Unknown mode: {mode}. Choose from: {self.MODES}")

        # Use LLM if API key is available
        if self.api_key:
            prompts = self.prompt_engine.build_prompt(text, mode)
            return await self._call_llm(prompts["system"], prompts["user"])

        # Fall back to rule-based transformation
        return self._rule_based_fallback(text, mode)

    async def make_concise(self, text: str) -> str:
        return await self.rewrite(text, "concise")

    async def simplify(self, text: str) -> str:
        return await self.rewrite(text, "simplify")

    async def formalize(self, text: str) -> str:
        return await self.rewrite(text, "formalize")

    async def casualize(self, text: str) -> str:
        return await self.rewrite(text, "casualize")

    async def summarize(self, text: str) -> str:
        return await self.rewrite(text, "summarize")

    async def expand(self, text: str) -> str:
        return await self.rewrite(text, "expand")

"""Prompt Templates for ProseAI rewriting modes."""
from typing import Dict, List


class PromptTemplateEngine:
    """Manages prompt templates for each rewriting mode."""

    TEMPLATES = {
        "concise": {
            "system": (
                "You are an expert editor specializing in concise writing. "
                "Remove redundancy, filler words, and unnecessary phrases. "
                "Preserve the core meaning and tone. Return only the rewritten text."
            ),
            "user": "Make this text more concise without losing meaning:\n\n{text}",
        },
        "simplify": {
            "system": (
                "You are a plain-language specialist. Rewrite text so a 10-year-old "
                "can understand it. Use short sentences, common words, and active voice. "
                "Return only the rewritten text."
            ),
            "user": "Simplify this text for a general audience:\n\n{text}",
        },
        "formalize": {
            "system": (
                "You are a professional writing consultant. Convert informal text "
                "into polished, formal language suitable for business or academic use. "
                "Maintain the original meaning. Return only the rewritten text."
            ),
            "user": "Rewrite this text in a formal, professional tone:\n\n{text}",
        },
        "casualize": {
            "system": (
                "You are a conversational writing expert. Transform formal or stiff "
                "text into friendly, approachable language. Use contractions and a "
                "warm tone. Return only the rewritten text."
            ),
            "user": "Rewrite this text in a casual, friendly tone:\n\n{text}",
        },
        "summarize": {
            "system": (
                "You are a summarization specialist. Distill the text to its key "
                "points, preserving the most important information. Aim for roughly "
                "25-30% of the original length. Return only the summary."
            ),
            "user": "Summarize the following text:\n\n{text}",
        },
        "expand": {
            "system": (
                "You are a content expansion expert. Elaborate on the given text "
                "by adding relevant details, examples, and explanations. Roughly "
                "double the length while keeping it coherent. Return only the expanded text."
            ),
            "user": "Expand and elaborate on this text:\n\n{text}",
        },
    }

    def list_modes(self) -> List[str]:
        """Return available rewriting modes."""
        return list(self.TEMPLATES.keys())

    def build_prompt(self, text: str, mode: str) -> Dict[str, str]:
        """Build system and user prompts for the given mode."""
        if mode not in self.TEMPLATES:
            raise ValueError(f"Unknown mode: {mode}. Available: {self.list_modes()}")
        template = self.TEMPLATES[mode]
        return {
            "system": template["system"],
            "user": template["user"].format(text=text),
        }
